[CmdletBinding(SupportsShouldProcess=$true)]
param(
 [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
 [ValidateRange(1,20)][int]$RunsPerArm=5,
 [ValidateRange(30,600)][int]$SampleSeconds=120,
 [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
 [switch]$AllowAutomaticReboot,
 [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
 [string]$RunDirectory,
 [string]$ControllerPath="$PSScriptRoot\..\..\controller\providers\HPAppHelperDemandStart.ps1"
)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$TaskName='Lacksan-EXP-063-LabHarness';$ServiceName='HPAppHelperCap';$ActivePointer=Join-Path $EvidenceRoot 'active.json'
function Test-Elevation {$p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent());if(-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required'}}
function Ensure-Directory([string]$Path){if(-not(Test-Path -LiteralPath $Path)){New-Item -ItemType Directory -Path $Path -Force|Out-Null}}
function Write-Json([string]$Path,$Value){$Value|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $Path -Encoding UTF8}
function Read-Json([string]$Path){if(-not(Test-Path -LiteralPath $Path)){throw "Required state missing: $Path"};Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json}
function Get-BootUtc {((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function Get-Median($Values){$v=@($Values|Where-Object {$null-ne$_}|ForEach-Object {[double]$_}|Sort-Object);if(!$v.Count){return $null};$m=[int][math]::Floor($v.Count/2);if($v.Count%2){return [double]$v[$m]};([double]$v[$m-1]+[double]$v[$m])/2}
function Get-Mad($Values){$v=@($Values|Where-Object {$null-ne$_}|ForEach-Object {[double]$_});if(!$v.Count){return $null};$m=Get-Median $v;Get-Median @($v|ForEach-Object {[math]::Abs($_-$m)})}
function Paths([string]$Dir){[pscustomobject]@{State=(Join-Path $Dir 'harness-state.json');ControllerState=(Join-Path $Dir 'controller-state.json');ControllerLog=(Join-Path $Dir 'controller-events.jsonl');Summary=(Join-Path $Dir 'summary.json')}}
function Resolve-RunDirectory {if($RunDirectory){return (Resolve-Path -LiteralPath $RunDirectory).Path};$a=Read-Json $ActivePointer;if(!$a.runDirectory){throw 'Active run pointer invalid'};(Resolve-Path -LiteralPath ([string]$a.runDirectory)).Path}
function Log([string]$Dir,[string]$Event,[hashtable]$Data){$row=[ordered]@{utc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-063';component='lab-harness';action=$Action;event=$Event;computer=$env:COMPUTERNAME;data=$Data};($row|ConvertTo-Json -Compress -Depth 10)|Add-Content -LiteralPath (Join-Path $Dir 'lab-events.jsonl') -Encoding UTF8}
function Controller([string]$ControllerAction,[string]$Dir){$p=Paths $Dir;& $ControllerPath -Action $ControllerAction -StatePath $p.ControllerState -LogPath $p.ControllerLog}
function Task {Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue}
function Register-ResumeTask([string]$Dir){if(Task){throw "Scheduled task already exists: $TaskName"};$exe=(Get-Command powershell.exe -ErrorAction Stop).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$Dir`" -EvidenceRoot `"$EvidenceRoot`" -ControllerPath `"$ControllerPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$user=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $user;$pr=New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 20);if($PSCmdlet.ShouldProcess($TaskName,'Register reboot continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Settings $s|Out-Null}}
function Remove-ResumeTask([string]$Dir){if(Task){if($PSCmdlet.ShouldProcess($TaskName,'Remove reboot continuation task')){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false;Log $Dir 'task-removed' @{task=$TaskName}}}}
function ProtectedSnapshot {$services=@();foreach($n in 'Tailscale','TermService'){try{$s=Get-Service $n -ErrorAction Stop;$services+=[pscustomobject]@{name=$n;status=$s.Status.ToString();startType=$s.StartType.ToString()}}catch{$services+=[pscustomobject]@{name=$n;status='absent';startType=$null}}};$processes=@(Get-Process -ErrorAction SilentlyContinue|Where-Object {$_.ProcessName-match'(?i)tailscale|msrdc|windowsapp|omnissa|horizon|vmware-view|wswc'}|Select-Object ProcessName,Id,Responding);[pscustomobject]@{services=$services;processes=$processes}}
function ServiceSnapshot {$s=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction Stop;$proc=$null;if([int]$s.ProcessId-gt0){$gp=Get-Process -Id ([int]$s.ProcessId) -ErrorAction SilentlyContinue;$wp=Get-CimInstance Win32_Process -Filter "ProcessId=$($s.ProcessId)" -ErrorAction SilentlyContinue;if($gp-and$wp){$proc=[ordered]@{pid=[int]$s.ProcessId;cpuMs=[double]$gp.TotalProcessorTime.TotalMilliseconds;workingSetBytes=[int64]$gp.WorkingSet64;readBytes=[uint64]$wp.ReadTransferCount;writeBytes=[uint64]$wp.WriteTransferCount}}};[pscustomobject]@{name=$s.Name;startMode=$s.StartMode;state=$s.State;process=$proc}}
function SystemSample {$cpu=(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;$disk=(Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec;[pscustomobject]@{cpu=[double]$cpu;disk=[double]$disk}}
function Collect([string]$Phase,[int]$Ordinal,[string]$Dir){$boot=Get-BootUtc;$before=ServiceSnapshot;$pb=ProtectedSnapshot;$collectorBefore=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$samples=@();$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds);for($i=0;$i-lt$count;$i++){$samples+=SystemSample;if($i-lt$count-1){Start-Sleep -Seconds $SampleIntervalSeconds}};$after=ServiceSnapshot;$collectorAfter=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$cpuDelta=$null;$readDelta=$null;$writeDelta=$null;if($before.process-and$after.process-and$before.process.pid-eq$after.process.pid){$cpuDelta=[double]$after.process.cpuMs-[double]$before.process.cpuMs;$readDelta=[double]$after.process.readBytes-[double]$before.process.readBytes;$writeDelta=[double]$after.process.writeBytes-[double]$before.process.writeBytes};$explorer=Get-Process explorer -ErrorAction SilentlyContinue|Sort-Object StartTime|Select-Object -First 1;[ordered]@{schema=1;experiment='EXP-063';phase=$Phase;ordinal=$Ordinal;computer=$env:COMPUTERNAME;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');desktopProxy=[ordered]@{explorerPresent=[bool]$explorer;explorerResponding=if($explorer){[bool]$explorer.Responding}else{$false};bootToExplorerStartMs=if($explorer){($explorer.StartTime.ToUniversalTime()-$boot).TotalMilliseconds}else{$null}};system=[ordered]@{cpuMedianPercent=(Get-Median @($samples|%{$_.cpu}));cpuMadPercent=(Get-Mad @($samples|%{$_.cpu}));diskMedianBytesPerSec=(Get-Median @($samples|%{$_.disk}));diskMadBytesPerSec=(Get-Mad @($samples|%{$_.disk}))};service=[ordered]@{before=$before;after=$after;cpuDeltaMs=$cpuDelta;readDeltaBytes=$readDelta;writeDeltaBytes=$writeDelta;startedDuringSample=(!$before.process-and$after.process)};protected=[ordered]@{before=$pb;after=(ProtectedSnapshot)};instrumentation=[ordered]@{collectorCpuDeltaMs=($collectorAfter-$collectorBefore);sampleCount=$samples.Count};functional=[ordered]@{hpApplicationDemandStart='needs-evidence';hpSupportAssistant='needs-evidence';hpUpdateDiscovery='needs-evidence'}}}
function Summarize([string]$Dir){$runs=@(Get-ChildItem $Dir -Filter 'run-*.json' -File|Sort-Object Name|%{Read-Json $_.FullName});if(!$runs.Count){throw 'No runs found'};$groups=[ordered]@{};foreach($phase in 'Baseline','Treatment'){$g=@($runs|?{$_.phase-eq$phase});$groups[$phase]=[ordered]@{runs=$g.Count;bootToExplorerStartMs=[ordered]@{median=(Get-Median @($g|%{$_.desktopProxy.bootToExplorerStartMs}));mad=(Get-Mad @($g|%{$_.desktopProxy.bootToExplorerStartMs}))};cpuMedianPercent=[ordered]@{median=(Get-Median @($g|%{$_.system.cpuMedianPercent}));mad=(Get-Mad @($g|%{$_.system.cpuMedianPercent}))};diskMedianBytesPerSec=[ordered]@{median=(Get-Median @($g|%{$_.system.diskMedianBytesPerSec}));mad=(Get-Mad @($g|%{$_.system.diskMedianBytesPerSec}))};serviceCpuDeltaMs=[ordered]@{median=(Get-Median @($g|%{$_.service.cpuDeltaMs}));mad=(Get-Mad @($g|%{$_.service.cpuDeltaMs}))}}};$summary=[ordered]@{schema=1;experiment='EXP-063';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');computer=$env:COMPUTERNAME;groups=$groups;limitations=@('bootToExplorerStartMs is a desktop-readiness proxy','HP application demand-start and update discovery remain physical functional checks')};Write-Json (Join-Path $Dir 'summary.json') $summary;$summary}
function RebootIfAllowed([string]$Dir){if($AllowAutomaticReboot){Log $Dir 'reboot-requested' @{};Restart-Computer -Force}else{Log $Dir 'reboot-required' @{};Write-Output 'Reboot required. Continue resumes automatically at next logon.'}}
Test-Elevation;if(!(Test-Path -LiteralPath $ControllerPath)){throw 'Controller missing'}
switch($Action){
'Start'{Ensure-Directory $EvidenceRoot;if(Test-Path $ActivePointer){throw 'An active EXP-063 run already exists'};$check=Controller 'Check' $EvidenceRoot;Controller 'DryRun' $EvidenceRoot|Out-Null;if($WhatIfPreference){$null=$PSCmdlet.ShouldProcess($TaskName,"Prepare $RunsPerArm baseline and treatment boots");return $check};$dir=Join-Path $EvidenceRoot ((Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss'));Ensure-Directory $dir;$p=Paths $dir;Controller 'Capture' $dir|Out-Null;$state=[ordered]@{schema=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null;sampleSeconds=$SampleSeconds;sampleIntervalSeconds=$SampleIntervalSeconds};Write-Json $p.State $state;Write-Json $ActivePointer @{runDirectory=$dir};Register-ResumeTask $dir;Log $dir 'started' @{runsPerArm=$RunsPerArm};RebootIfAllowed $dir}
'Continue'{$dir=Resolve-RunDirectory;$p=Paths $dir;$state=Read-Json $p.State;$boot=(Get-BootUtc).ToString('o');if($state.lastBootUtc-eq$boot){throw 'Duplicate collection from same boot refused'};if($state.phase-eq'Treatment'){Controller 'VerifyReboot' $dir|Out-Null}else{$orig=Read-Json $p.ControllerState;$cur=Controller 'Check' $dir;if($cur.Service.StartMode-ne$orig.service.StartMode-or[int]$cur.Service.DelayedAutoStart-ne[int]$orig.service.DelayedAutoStart){throw 'Baseline configuration drift detected'}};$ordinal=[int]$state.completedRuns+1;$trial=Collect $state.phase $ordinal $dir;Write-Json (Join-Path $dir ("run-{0}-{1:D2}.json"-f$state.phase,$ordinal)) $trial;$state.completedRuns=$ordinal;$state.lastBootUtc=$boot;if($state.completedRuns-ge[int]$state.runsPerArm){if($state.phase-eq'Baseline'){$state.phase='Treatment';$state.completedRuns=0;Controller 'Apply' $dir|Out-Null}else{Controller 'Rollback' $dir|Out-Null;Summarize $dir|Out-Null;Remove-ResumeTask $dir;Remove-Item $ActivePointer -Force;Write-Json $p.State $state;Log $dir 'completed' @{};return(Read-Json $p.Summary)}};Write-Json $p.State $state;Log $dir 'trial-collected' @{phase=$trial.phase;ordinal=$ordinal};RebootIfAllowed $dir}
'Status'{if(Test-Path $ActivePointer){$dir=Resolve-RunDirectory;Read-Json (Paths $dir).State}else{[pscustomobject]@{active=$false}}}
'Summarize'{$dir=Resolve-RunDirectory;Summarize $dir}
'Stop'{$dir=Resolve-RunDirectory;$p=Paths $dir;Controller 'Rollback' $dir|Out-Null;Remove-ResumeTask $dir;Remove-Item $ActivePointer -Force -ErrorAction SilentlyContinue;Log $dir 'stopped' @{};[pscustomobject]@{stopped=$true;runDirectory=$dir}}
}